const frame = context.panel.data.series[0];
if (!frame) {
  return { title: { text: 'Sem dados', left: 'center', top: 'middle' } };
}
const coluna = (nome) => {
  const campo = frame.fields.find((f) => f.name === nome);
  return campo ? Array.from(campo.values) : [];
};

const sensores = [
  ['mq3_raw', 'MQ-3'],
  ['mq135_raw', 'MQ-135'],
  ['humidity_pct', 'Umidade (%)'],
  ['temperature_c', 'Temperatura (°C)'],
];
const casos = coluna('caso');
const nomesCasos = [...new Set(casos)].sort();

const quartis = (valores) => {
  const v = valores.filter((x) => x !== null && !Number.isNaN(x)).sort((a, b) => a - b);
  if (v.length === 0) {
    return [];
  }
  const q = (p) => {
    const i = (v.length - 1) * p;
    const base = Math.floor(i);
    return v[base] + (v[Math.min(base + 1, v.length - 1)] - v[base]) * (i - base);
  };
  return [v[0], q(0.25), q(0.5), q(0.75), v[v.length - 1]];
};

const grids = [];
const xAxis = [];
const yAxis = [];
const title = [];
const series = [];
sensores.forEach(([campo, nome], i) => {
  const valores = coluna(campo);
  const esquerda = i % 2 === 0 ? 6 : 54;
  const topo = i < 2 ? 8 : 56;
  grids.push({ left: `${esquerda}%`, top: `${topo}%`, width: '40%', height: '32%' });
  title.push({ text: nome, left: `${esquerda}%`, top: `${topo - 6}%`, textStyle: { fontSize: 12 } });
  xAxis.push({ type: 'category', data: nomesCasos, gridIndex: i, axisLabel: { fontSize: 10 } });
  yAxis.push({ type: 'value', gridIndex: i, scale: true });
  series.push({
    name: nome,
    type: 'boxplot',
    xAxisIndex: i,
    yAxisIndex: i,
    data: nomesCasos.map((caso) => quartis(valores.filter((_, k) => casos[k] === caso))),
  });
});

return { title, grid: grids, xAxis, yAxis, series, tooltip: { trigger: 'item' } };

const frame = context.panel.data.series[0];
if (!frame) {
  return { title: { text: 'Sem dados', left: 'center', top: 'middle' } };
}
const coluna = (nome) => {
  const campo = frame.fields.find((f) => f.name === nome);
  return campo ? Array.from(campo.values) : [];
};

const sensores = ['MQ-3', 'MQ-135', 'Umidade (%)', 'Temperatura (°C)'];
const casos = coluna('caso');
const dados = [];
sensores.forEach((sensor, x) => {
  const medias = coluna(sensor);
  const validas = medias.filter((m) => m !== null);
  const menor = Math.min(...validas);
  const maior = Math.max(...validas);
  medias.forEach((media, y) => {
    if (media === null) {
      return;
    }
    const normalizada = maior > menor ? (media - menor) / (maior - menor) : 0.5;
    dados.push({ value: [x, y, normalizada], media });
  });
});

return {
  tooltip: {
    formatter: (p) => `${casos[p.value[1]]} · ${sensores[p.value[0]]}: média ${p.data.media.toFixed(1)}`,
  },
  grid: { left: 110, right: 30, top: 10, bottom: 70 },
  xAxis: { type: 'category', data: sensores, axisLabel: { interval: 0 } },
  yAxis: { type: 'category', data: casos },
  visualMap: {
    min: 0, max: 1, calculable: true, orient: 'horizontal', left: 'center', bottom: 0,
    text: ['maior média', 'menor média'],
  },
  series: [{
    type: 'heatmap',
    data: dados,
    label: { show: true, formatter: (p) => p.data.media.toFixed(0) },
  }],
};
